import{_ as r,C as s,c as l,o as f,ag as a,j as e,G as n,a as i}from"./chunks/framework.Bw-5EFTY.js";const w=JSON.parse('{"title":"GiveWP Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/givewp-integration-with-fluentaffiliate.md","filePath":"guide/integrations/givewp-integration-with-fluentaffiliate.md","lastUpdated":1755603747000}'),g={name:"guide/integrations/givewp-integration-with-fluentaffiliate.md"};function u(c,t,d,p,h,m){const o=s("ZoomableImage");return f(),l("div",null,[t[0]||(t[0]=a('<h1 id="givewp-integration-with-fluentaffiliate" tabindex="-1">GiveWP Integration with FluentAffiliate <a class="header-anchor" href="#givewp-integration-with-fluentaffiliate" aria-label="Permalink to &quot;GiveWP Integration with FluentAffiliate&quot;">​</a></h1><p>Integrating GiveWP with the FluentAffiliate plugin helps you to manage affiliates of your donation campaigns, memberships, and course purchases. In this guide, we’ll walk you through the steps to connect GiveWP with FluentAffiliate and set up affiliate commission for your campaign.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>GiveWP is a pro feature of FluentAffiliate. To use it, you need FluentAffiliate Pro.</p><p>To get started, you must first install and activate the GiveWP plugin on your WordPress website.</p></div><h2 id="enable-givewp-in-fluentaffiliate" tabindex="-1">Enable GiveWP in FluentAffiliate <a class="header-anchor" href="#enable-givewp-in-fluentaffiliate" aria-label="Permalink to &quot;Enable GiveWP in FluentAffiliate&quot;">​</a></h2><p>Once you have both plugins activated, follow these steps to connect GiveWP with FluentAffiliate:</p><ol><li>Go to the <strong>FluentAffiliate Dashboard</strong>.</li><li>From there, click on the <strong>Settings</strong> tab in the top right corner.</li><li>On the left sidebar, you’ll find an option called <strong>Integration Settings</strong>. Simply click on that.</li><li>Inside Integration Settings, you’ll see a list of different integration options. Find <strong>GiveWP</strong> in this list.</li><li>Now, simply click on the <strong>toggle</strong> button to enable GiveWP integration with FluentAffiliate to track donations.</li><li>Your <strong>GiveWP</strong> integration with <strong>FluentAffiliate</strong> is now active, allowing affiliates to earn referral commissions on GiveWP Campaign and Course sales.</li></ol><p>In the <strong>Manage</strong> section, you’ll find additional settings to customize how affiliate commissions work with your GiveWP donation campaign, memberships, and courses.</p>',7)),e("p",null,[n(o,{src:"/guide/public/images/integrations/givewp/integration-setup-options.webp",alt:"Integration Settings"})]),t[1]||(t[1]=a('<h3 id="configure-givewp-settings" tabindex="-1">Configure GiveWP Settings <a class="header-anchor" href="#configure-givewp-settings" aria-label="Permalink to &quot;Configure GiveWP Settings&quot;">​</a></h3><p>After clicking the Manage button, you can configure how affiliate commissions are handled for your donation forms.</p><ul><li><strong>Enable Affiliate Integration for GiveWP:</strong> You must check this box to activate commission tracking for all your GiveWP donation forms.</li><li><strong>Enable custom rate for specific donation forms:</strong> Check this box if you want to override the default commission rate and set special rates for different donation forms.</li></ul><h3 id="custom-affiliate-rate-configuration" tabindex="-1">Custom Affiliate Rate Configuration <a class="header-anchor" href="#custom-affiliate-rate-configuration" aria-label="Permalink to &quot;Custom Affiliate Rate Configuration&quot;">​</a></h3><p>Once <strong>Enable custom rate</strong> is checked, you can define specific commission structures for individual donation forms. This is perfect for rewarding affiliates differently for various campaigns.</p><p>Click on the <strong>+Add New Group</strong> button to create your first custom rate.</p><ol><li><strong>GiveWP Forms:</strong> This option allows you to apply the custom rate to a specific donation form. Enter a keyword in the text field to search for and select the form to which this custom rate will apply.</li><li><strong>Select Rate:</strong> Set the commission rate for the selected form.Enter a numerical value into the field to set the commission amount.</li></ol><ul><li><strong>Rate Type Selector:</strong> Click the dropdown menu to choose the type of commission: <ul><li><strong>Percentage:</strong> The affiliate will receive a percentage of the donation amount.</li><li><strong>Fixed:</strong> The affiliate will receive a fixed amount as commission, regardless of the donation amount.</li></ul></li></ul><ol start="3"><li><strong>Add More Rates:</strong> After configuring a rate, you can click the <strong>+Add New Group</strong> button again to add more custom rates for other donation forms. You can also delete a rate by clicking the delete icon on the right side.</li></ol><p>Once all your custom rates are added, click the <strong>Save Settings</strong> button to apply them.</p>',10)),e("p",null,[n(o,{src:"/guide/public/images/integrations/givewp/givewp-settings-configuration.webp",alt:"GiveWP Settings"})]),t[2]||(t[2]=e("h3",{id:"generate-an-affiliate-link",tabindex:"-1"},[i("Generate an Affiliate Link "),e("a",{class:"header-anchor",href:"#generate-an-affiliate-link","aria-label":'Permalink to "Generate an Affiliate Link"'},"​")],-1)),t[3]||(t[3]=e("p",null,[i("After you’ve completed configuring the GiveWP settings, the next step is to log in to your "),e("strong",null,"Affiliate Area"),i(" provided by FluentAffiliate. To learn more about how can generate your "),e("a",{href:"/guide/affiliate-portal/generating-affiliate-links"},"affiliate link"),i(", read this article.")],-1)),t[4]||(t[4]=e("p",null,[i("If someone purchases the campaign or courses using your affiliate link, you’ll earn a "),e("strong",null,"commission"),i(" based on the settings you’ve configured.")],-1)),e("p",null,[n(o,{src:"/guide/public/images/integrations/givewp/affiliate-link-generation.webp",alt:"Copy Affiliate Link"})]),t[5]||(t[5]=e("p",null,"And that’s it! This is the easy process to integrate GiveWP with FluentAffiliate and start earning commissions.",-1))])}const b=r(g,[["render",u]]);export{w as __pageData,b as default};
